var p=H.page('Proto macOS Light');var s=p.layers.find(function(l){return l.name==='Screen/macos/Light/Clean/settings';});var n=0;sketch.find('Group',s).forEach(function(l){if(l.frame.width===26&&l.frame.height===15){l.style.borders=[{color:H.alpha(H.hex('Light/Clean','ink'),0.12),thickness:0.5,enabled:true,position:sketch.Style.BorderPosition.Inside}];l.layers.forEach(function(k){k.style.shadows=[{color:'#00000038',blur:1.5,x:0,y:0.5,spread:0}];});n++;}});console.log(JSON.stringify({toggles:n,id:s.id}));